#!/usr/bin/env bash
# Builds what the rustorb Python client and server need, on the host:
# the rustorb package with its native module (and the omniORB
# compatibility package) in lib/, and the stubs of
# the interop IDL files and CosNaming.idl, generated by rustorb-idl, in stubs/.
# run-matrix.sh runs it; idl_parser must be importable, or IDL_PARSER_DIR
# set to a checkout of it.
#
# The native module is a stable ABI (abi3) extension that does not link to
# libpython, so the one built on the host loads in the Python of the
# interop image.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$here/../../.."

PYO3_BUILD_EXTENSION_MODULE=1 cargo build --release --locked -p rustorb-python \
  --manifest-path "$root/Cargo.toml"

rm -rf "$here/lib" "$here/stubs"
mkdir -p "$here/lib" "$here/stubs"
cp -r "$root/python/rustorb" "$here/lib/"
# The omniORBpy compatibility package, for scripts/timeout-probe.
cp -r "$root/python/omniorb-compat/omniORB" "$here/lib/"
rm -rf "$here"/lib/rustorb/_native* "$here"/lib/rustorb/__pycache__
case "$(uname -s)" in
  Darwin) cp "$root/target/release/lib_native.dylib" "$here/lib/rustorb/_native.abi3.so" ;;
  *) cp "$root/target/release/lib_native.so" "$here/lib/rustorb/_native.abi3.so" ;;
esac

pythonpath="$root/crates/rustorb-codegen/python"
[ -n "${IDL_PARSER_DIR:-}" ] && pythonpath="$IDL_PARSER_DIR:$pythonpath"
PYTHONPATH="$pythonpath" python3 -m rustorb_idl -bpython -C "$here/stubs" -I"$root/interop/idl" \
  "$root/interop/idl/InteropTest.idl" "$root/interop/idl/AnyTest.idl" \
  "$root/interop/idl/AnyTestHidden.idl" "$root/interop/idl/ValueTest.idl" \
  "$root/interop/idl/CustomTest.idl" "$root/interop/idl/AbstractTest.idl" \
  "$root/interop/idl/PoaProbe.idl" \
  "$root/crates/rustorb-codegen/tests/idl/CosNaming.idl"
